function svgLinha(series,opt){opt=opt||{};const W=opt.w||560,H=opt.h||200,pl=34,pr=12,pt=14,pb=34;const n=Math.max(...series.map(s=>s.v.length),1);const x=k=>pl+(n<=1?(W-pl-pr)/2:k*(W-pl-pr)/(n-1));const y=v=>pt+(1-Math.max(0,Math.min(1,v)))*(H-pt-pb);
  const sec=opt.sec;const grid=[0,.25,.5,.75,1].map(g=>`<line x1="${pl}" x2="${W-pr}" y1="${y(g)}" y2="${y(g)}" class="lg ${g===.5?'l50':''}"/><text x="${pl-6}" y="${y(g)+4}" class="lt" text-anchor="end">${sec?Math.round(g*20):Math.round(g*100)}</text>`).join('');
  const esp=n>1?(W-pl-pr)/(n-1):W-pl-pr;const alt=n>2&&esp<86;const cap=Math.max(5,Math.floor((alt?esp*2:esp)/6.4)-1);const lab=(opt.labels||[]).map((l,k,A_)=>{const tx=l.length>cap?l.slice(0,cap-1).trim()+'…':l;const anc=A_.length>1&&k===0?'start':A_.length>1&&k===A_.length-1?'end':'middle';return `<text x="${x(k)}" y="${alt&&k%2?H-3:H-17}" class="lt" text-anchor="${anc}"><title>${esc(l)}</title>${esc(tx)}</text>`}).join('');
  const pa=series.map(s=>{const pts=s.v.map((v,k)=>v==null?null:[x(k),y(v)]).filter(Boolean);if(!pts.length)return '';const d='M'+pts.map(p=>p.join(',')).join('L');
    return `<path d="${d}" class="ll ${s.cls||''}" style="stroke:${s.cor}" pathLength="1"/>${pts.map(p=>`<circle cx="${p[0]}" cy="${p[1]}" r="${s.r||3.5}" style="fill:${s.cor}" class="lp"/>`).join('')}`}).join('');
  return `<svg viewBox="0 0 ${W} ${H}" class="lchart" role="img" aria-label="${esc(opt.aria||'Gráfico')}">${grid}${lab}${pa}</svg>`}
function domAnalise(t,d){const al=alunosAval(t),P=periodos();const insts=t.instrumentos.filter(i=>i.itens.some(x=>x.dom===d.id)).sort((a,b)=>(+a.periodo-+b.periodo)||(a.data||'').localeCompare(b.data||''));
  const S_=al.map(a=>{const v=insts.map(i=>{const x=instDom(i,a.id,d.id);return x?x.pct:null});const pp=P.map(p=>domPer(t,a.id,d.id,p));const m=avg(pp.filter(x=>x!=null));const vv=v.filter(x=>x!=null);const tend=vv.length>=2?vv[vv.length-1]-vv[0]:null;
    return {a,v,pp,m,tend,min:vv.length?Math.min(...vv):null,max:vv.length?Math.max(...vv):null,n:vv.length}});
  const ok=S_.filter(x=>x.m!=null);const M=ok.map(x=>x.m);const med=avg(M);const mdn=stMed(M);const dp=stDP(M);const pos=ok.filter(x=>!negativa(t,x.m)).length;
  const media_i=insts.map(i=>avg(al.map(a=>{const x=instDom(i,a.id,d.id);return x&&x.pct})));
  const ord=ok.slice().sort((x,y)=>y.m-x.m);
  return {al,P,insts,S:S_,ok,med,mdn,dp,pos,media_i,melhor:ord[0],pior:ord[ord.length-1],sobe:ok.filter(x=>x.tend!=null).sort((x,y)=>y.tend-x.tend)[0],desce:ok.filter(x=>x.tend!=null).sort((x,y)=>x.tend-y.tend)[0]}}
function domFichaAluno(t,d,X,o,tipo){if(!o)return '';const c=domCor(t,d);const vs=X.v||o.v;const dif=o.m-X.med;const fortes=X.insts.map((i,k)=>({i,v:o.v[k],m:X.media_i[k]})).filter(z=>z.v!=null);
  const best=fortes.slice().sort((a,b)=>(b.v-b.m)-(a.v-a.m))[0],worst=fortes.slice().sort((a,b)=>(a.v-a.m)-(b.v-b.m))[0];
  return `<div class="dfa ${tipo}"><div class="dfah">${avatar(o.a,44)}<div><small>${tipo==='top'?'🏆 Melhor desempenho':'🎯 Precisa de mais apoio'}</small><b>${esc(o.a.nome)}</b><span class="mut">n.º ${esc(numAl(o.a))} · ${o.n} instrumento${o.n!==1?'s':''}</span></div><span class="sp1"></span><span class="dfan" style="color:${c}">${pctD(t,o.m)}</span></div>
    ${svgLinha([{v:o.v,cor:c,r:4},{v:X.media_i,cor:'#94a3b8',cls:'dash',r:2.5}],{w:420,h:150,labels:X.insts.map(i=>i.nome),sec:isSec(t),aria:'Evolução de '+o.a.nome})}
    <ul class="dfal"><li>${dif>=0?'▲':'▼'} <b>${isSec(t)?(Math.abs(dif)*20).toFixed(1).replace('.',',')+' valores':Math.round(Math.abs(dif)*100)+' pp'}</b> ${dif>=0?'acima':'abaixo'} da média da turma</li>
      <li>Intervalo: ${pctD(t,o.min)} – ${pctD(t,o.max)}${o.tend!=null?` · evolução ${o.tend>=0?'+':'−'}${isSec(t)?(Math.abs(o.tend)*20).toFixed(1).replace('.',','):Math.round(Math.abs(o.tend)*100)+' pp'}`:''}</li>
      ${best?`<li>Melhor momento: <b>${esc(best.i.nome)}</b> (${pctD(t,best.v)} vs ${pctD(t,best.m)} da turma)</li>`:''}${worst&&worst!==best?`<li>Momento mais difícil: <b>${esc(worst.i.nome)}</b> (${pctD(t,worst.v)})</li>`:''}</ul>
    <button type="button" class="btn sm" data-dfp="${o.a.id}">${ic('user',13)} Perfil de Aprendizagem</button></div>`}
